// store.js — small Svelte stores that wrap the Wails bindings.
// All wailsjs/* modules are auto-generated by `wails dev` and
// `wails build`, so they live under frontend/wailsjs/go and
// frontend/wailsjs/runtime. We import them at the top.

import { writable } from 'svelte/store';
import {
  GetSettings,
  SaveSettings,
  GetStatus,
  ResetCounter,
} from '../../wailsjs/go/main/App.js';
import { EventsOn, EventsOff } from '../../wailsjs/runtime/runtime.js';

// settings is a writable store seeded synchronously with the
// saved config. We populate it on app boot via initSettings().
export const settings = writable({
  poll_interval_ms: 500,
  enabled: true,
  direction: 's2t',
  start_with_windows: false,
  start_minimized: false,
  write_back_to_clipboard: true,
});

// status is a writable store for the live Status snapshot.
export const status = writable({
  enabled: true,
  running: false,
  counter: 0,
  clipboard_head: '',
  last_event: null,
  last_updated: null,
});

// history is an in-memory ring buffer of the most recent conversion
// events. JS-side only — resets on app restart, which is fine for v1.
export const history = writable([]);
const MAX_HISTORY = 50;
let nextId = 0;
function pushHistory(ev) {
  history.update((arr) => {
    const id = ++nextId;
    return [{ ...ev, id }, ...arr].slice(0, MAX_HISTORY);
  });
}

// initSettings / initStatus bootstrap the stores from the Go side.
export async function initSettings() {
  try {
    const s = await GetSettings();
    settings.set(s);
  } catch (e) {
    console.error('GetSettings failed:', e);
  }
}

export async function refreshStatus() {
  try {
    const s = await GetStatus();
    status.set(s);
  } catch (e) {
    console.error('GetStatus failed:', e);
  }
}

// saveSettings wraps SaveSettings and updates the local store.
export async function saveSettings(patch) {
  let cur;
  settings.subscribe((v) => (cur = v))();
  const merged = { ...cur, ...patch };
  try {
    const saved = await SaveSettings(merged);
    settings.set(saved);
    return saved;
  } catch (e) {
    console.error('SaveSettings failed:', e);
    throw e;
  }
}

// resetCounter resets the lifetime counter and refreshes status.
export async function resetCounter() {
  try {
    await ResetCounter();
    await refreshStatus();
  } catch (e) {
    console.error('ResetCounter failed:', e);
  }
}

// subscribeEvents wires all the Wails event listeners. Returns a
// teardown function that unsubscribes — call from onDestroy().
export function subscribeEvents() {
  const handlers = [
    EventsOn('clipboard:convert', (ev) => {
      status.update((s) => ({
        ...s,
        last_event: ev,
        last_updated: ev.when,
        counter: (s.counter ?? 0) + 1,
      }));
      pushHistory(ev);
    }),
    EventsOn('clipboard:skip', (ev) => {
      status.update((s) => ({ ...s, last_event: ev, last_updated: ev.when }));
      pushHistory(ev);
    }),
    EventsOn('clipboard:error', (ev) => {
      status.update((s) => ({ ...s, last_event: ev, last_updated: ev.when }));
      pushHistory(ev);
    }),
    EventsOn('settings:changed', (s) => settings.set(s)),
    EventsOn('settings:enabled', (b) =>
      settings.update((cur) => ({ ...cur, enabled: b })),
    ),
    EventsOn('counter:reset', () =>
      status.update((s) => ({ ...s, counter: 0 })),
    ),
  ];
  return () => handlers.forEach(EventsOff);
}

// helper: format an ISO timestamp as HH:MM:SS.
export function formatTime(iso) {
  if (!iso) return '--:--:--';
  try {
    const d = new Date(iso);
    return d.toTimeString().slice(0, 8);
  } catch {
    return '--:--:--';
  }
}